// Second-layer dedupe: only pass items we have never drafted before.
// The RSS trigger already emits only items newer than the last poll; this guards
// against restarts, overlapping polls, and feeds that re-publish the same item.
const store = $getWorkflowStaticData('global');
if (!Array.isArray(store.seenGuids)) store.seenGuids = [];
const seen = new Set(store.seenGuids);

const out = [];
for (const item of $input.all()) {
  const j = item.json;
  const key = j.guid || j.id || j.link || j.title || '';
  if (!key || seen.has(key)) continue;
  seen.add(key);
  out.push({ json: {
    guid: key,
    title: (j.title || '').toString().trim(),
    link: (j.link || '').toString().trim(),
    source: (j.creator || j.author || (j.link || '').toString().split('/')[2] || 'RSS').toString().trim(),
    snippet: (j.contentSnippet || j.content || j.summary || '').toString().replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 4000),
    pubDate: (j.isoDate || j.pubDate || '').toString()
  } });
}

// Persist, keeping only the most recent 1000 keys so static data stays small.
store.seenGuids = Array.from(seen).slice(-1000);

return out;

