// Robustly parse the model's draft into title + body.
const out = $input.first().json;
const text = (out.content && out.content[0] && out.content[0].text) ? out.content[0].text : '';

let title = '';
let body = '';
try {
  const cleaned = text.replace(/^```(?:json)?/i, '').replace(/```$/,'').trim();
  const obj = JSON.parse(cleaned);
  title = (obj.title || '').toString().trim();
  body = (obj.body || '').toString().trim();
} catch (e) {
  // Fallback: first non-empty line is the title, the rest is the body.
  const lines = text.split('\n').map(l => l.trim()).filter(Boolean);
  title = (lines.shift() || 'Untitled draft').replace(/^#+\s*/, '');
  body = lines.join('\n\n');
}

const src = $('Dedupe New Items').first().json;
return [{ json: {
  suggestedTitle: title || 'Untitled draft',
  draftBody: body || text,
  sourceTitle: src.title,
  sourceLink: src.link,
  source: src.source
} }];
